import os
import re

subjects = {
    "LLM": ["LLM", "Language Model", "Transformer", "GPT", "Attention", "BERT", "Large Language Model", "text generation", "NLP"],
    "trapped_ion_and_qc": ["trapped ion", "quantum computing", "qubit", "quantum gate", "Rabi", "quantum information", "entanglement", "ion trap", "quantum simulation"],
    "black_hole": ["black hole", "Schwarzschild", "Hawking", "event horizon", "gravity", "general relativity", "gravitational", "singularity", "Kerr"],
    "DNA": ["DNA", "genome", "nucleotide", "genetic", "sequencing", "chromosomes", "gene", "biological", "molecular"],
    "music_history": ["music", "composer", "renaissance", "baroque", "symphony", "history of music", "musical", "opera", "orchestra"]
}

def categorize(text):
    text = text.lower()
    scores = {s: 0 for s in subjects}
    for s, keywords in subjects.items():
        for k in keywords:
            if k.lower() in text:
                scores[s] += 1

    # Identify the best subject. If all 0, default to music_history as per instruction "it should fit into the last one"
    if all(score == 0 for score in scores.values()):
        return "music_history"

    # Order of subjects in the prompt: LLM, Trapped ion, Black hole, DNA, Music history.
    # If there's a tie, we should pick the one that matches best.
    best_subject = max(scores, key=scores.get)
    return best_subject

text_dir = "/tmp/paper_texts"
results = {}

for filename in os.listdir(text_dir):
    if filename.endswith(".txt"):
        with open(os.path.join(text_dir, filename), "r", errors="ignore") as f:
            content = f.read()
            original_filename = filename[:-4] # Remove .txt
            results[original_filename] = categorize(content)

for filename, subject in results.items():
    print(f"{filename} {subject}")

